-- Adaptation de campagne, pas un taux officiel entre les deux jeux.
-- Catalogue : valeurs sources exactes, migration rejouable. Soldes et boutique inchangés.
begin;
create temporary table currency_patch(id text, old_base text, new_base text) on commit drop;
