update bastide_scenario_items s set mechanical_base=p.new_base,updated_at=now() from currency_patch p where s.id=p.id and s.mechanical_base=p.old_base;
update bastide_players p set state=jsonb_set(p.state,'{inventory}',(select jsonb_agg(case when c.id is not null then jsonb_set(i.item,'{base}',to_jsonb(left(c.new_base,120))) else i.item end order by i.ord) from jsonb_array_elements(p.state->'inventory') with ordinality i(item,ord) left join currency_patch c on i.item->>'base'=left(c.old_base,120))),updated_at=now() where exists(select 1 from jsonb_array_elements(p.state->'inventory') i join currency_patch c on i->>'base'=left(c.old_base,120));
update bastide_scenario_items set title=replace(title,'50 po','50 PA'),description=replace(description,'50 pièces d’or','50 pièces d’argent'),mechanical_base=mechanical_base || ' Montant adapté Bastide : 50 PA (source D&D : 50 PO).',updated_at=now() where id='ch3-bourse-bureau-capitaine' and title like '%50 po';
update bastide_scenario_items set title=replace(title,'200 po','200 PA'),description=replace(description,'200 pièces d’or','200 pièces d’argent'),mechanical_base=mechanical_base || ' Montant adapté Bastide : 200 PA (source D&D : 200 PO).',updated_at=now() where id='ch3-cachette-200-po' and title like '%200 po';
update bastide_scenario_items set title=replace(title,'55 po','55 PA'),description=replace(description,'55 pièces d’or','55 pièces d’argent'),mechanical_base=mechanical_base || ' Montant adapté Bastide : 55 PA (source D&D : 55 PO).',updated_at=now() where id='ch3-sacoche-coffre-55-po' and title like '%55 po';
update bastide_scenario_items set title=replace(title,'10 po','10 PA'),description=replace(description,'10 pièces d’or','10 pièces d’argent'),mechanical_base=mechanical_base || ' Montant adapté Bastide : 10 PA (source D&D : 10 PO).',updated_at=now() where id='ch4-bourse-etude-10-po' and title like '%10 po';
update bastide_scenario_items set description='Trésor monétaire : 395 PA, à répartir entre les personnages.',mechanical_base=mechanical_base || ' Montant adapté Bastide : 395 PA. Source D&D : 4 500 PC, 2 200 PA, 130 PO.',updated_at=now() where id='ch4-tresor-monnaie-vrilleclair' and description='Trésor composé de 4 500 pièces de cuivre, 2 200 pièces d’argent et 130 pièces d’or.';
commit;
